"""Extract Moon's opacity table from the supplied original; never execute it."""
from pathlib import Path
from inspect_original import Original


def main():
    alpha = Original().unpack('<220B', 0x1a139c)
    lines = [
        '// Generated by game/tools/import_moon_visual.py from the supplied original.',
        '// Moon.updateAnimation: ARM table 0x1a139c, 220 opacity samples.',
        '#pragma once', '#include <algorithm>', '#include <array>', '#include <cmath>',
        '#include <cstdint>', 'namespace game::play {',
        'inline constexpr std::array<std::uint8_t,220> kMoonHighlightAlpha{{',
    ]
    lines += ['    ' + ','.join(str(v) for v in alpha[i:i+20]) + ',' for i in range(0,220,20)]
    lines += [
        '}};',
        '// Native update advances one sample per call at the original 60 Hz cadence.',
        '// Use elapsed time here so desktop frame rate does not change the duration.',
        'inline std::uint8_t moon_highlight_alpha(double seconds) {',
        '    const int frame=static_cast<int>(std::clamp(std::floor(seconds*60+1e-7),0.,219.));',
        '    return kMoonHighlightAlpha[frame];', '}', '}',
    ]
    target = Path(__file__).resolve().parents[1] / 'gameplay/moon_visual.h'
    target.write_text('\n'.join(lines) + '\n', encoding='utf8')
    print(target)


if __name__ == '__main__':
    main()
